import{_ as a,o as r,c as t,a4 as o}from"./chunks/framework.9tZL7ZIQ.js";const p=JSON.parse('{"title":"艾克·弗里德曼","description":"","frontmatter":{"title":"艾克·弗里德曼","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/艾克·弗里德曼.md","filePath":"04_people/艾克·弗里德曼.md"}'),s={name:"04_people/艾克·弗里德曼.md"};function i(l,e,n,h,_,d){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="艾克·弗里德曼" tabindex="-1">艾克·弗里德曼 <a class="header-anchor" href="#艾克·弗里德曼" aria-label="Permalink to &quot;艾克·弗里德曼&quot;">​</a></h1><ul><li><strong>角色职位</strong>：Borsheim&#39;s（波塞尔姆珠宝店）CEO</li><li><strong>与巴菲特关系</strong>：经巴菲特推荐、由苏珊·巴菲特引荐加入伯克希尔生态的珠宝零售商高管</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>艾克·弗里德曼是Borsheim&#39;s珠宝店的首席执行官。Borsheim&#39;s坐落于奥马哈，是全球最负盛名的珠宝零售商之一。该店与巴菲特的渊源极深——巴菲特本人正是通过妻子苏珊·巴菲特的推荐注意到了这家店，并最终将其纳入伯克希尔的资产组合。</p><p>弗里德曼在Borsheim&#39;s的领导下，将这家小店打造成了一个商业传奇。伯克希尔每年在奥马哈举办股东大会期间，Borsheim&#39;s都会迎来一年中最繁忙的销售高峰，来自全球的伯克希尔股东们纷纷慕名光顾。弗里德曼的管理风格既专业又富有亲和力，与巴菲特&quot;信任管理人才&quot;的哲学高度契合。</p><p>在弗里德曼的运营下，Borsheim&#39;s以其出色的客户服务、独特的商业氛围和稳定的财务表现，成为伯克希尔零售板块中的一颗明珠。巴菲特本人对这家珠宝店有着特殊的情感，常在股东信中提及。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1989年</strong>：Borsheim&#39;s被伯克希尔收购，艾克·弗里德曼继续担任CEO</li><li><strong>1990年代</strong>：在股东大会期间创下珠宝销售纪录</li><li><strong>21世纪初</strong>：继续领导Borsheim&#39;s，维持其在高端珠宝零售领域的地位</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search?q=Friedman&#39;s Inc.">1988年：完整翻译|/01_letters/1988年/翻译</a></li><li><a href="/search?q=Friedman&#39;s Inc.收购完成">1989年：完整翻译|/01_letters/1989年/翻译</a></li></ul>',11)])])}const m=a(s,[["render",i]]);export{p as __pageData,m as default};
